// StateFlow — recommended for new projects
private val _state = MutableStateFlow(UiState())
val state: StateFlow<UiState> = _state.asStateFlow()

// Collecting safely in Compose
@Composable
fun MyScreen(viewModel: MyViewModel) {
    val state by viewModel.state
        .collectAsStateWithLifecycle()
    Text(state.title)
}

class SearchViewModel(
    private val savedState: SavedStateHandle
) : ViewModel() {
    // Automatically saved & restored on process death
    val query = savedState.getStateFlow("query", "")

    fun onQueryChange(newQuery: String) {
        savedState["query"] = newQuery
        performSearch(newQuery)
    }
}

class ProfileViewModel : ViewModel() {
    private val _uiState = MutableStateFlow(ProfileState())
    val uiState: StateFlow<ProfileState> = _uiState.asStateFlow()

    fun loadProfile(userId: String) {
        viewModelScope.launch {
            val profile = repository.getProfile(userId)
            _uiState.update { it.copy(profile = profile) }
        }
    }
}

class ChatViewModel(private val socket: ChatSocket) : ViewModel() {
    private val manualScope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    init { socket.connect() }

    override fun onCleared() {
        socket.disconnect()        // release what this ViewModel opened
        manualScope.cancel()       // a scope you created yourself must be cancelled
    }                              // viewModelScope is cancelled for you before this runs
}

