class CounterViewModel : ViewModel() {
    private val _state = MutableStateFlow(CounterState())
    val state: StateFlow<CounterState> = _state.asStateFlow()   // read-only for the UI

    fun increment() {
        _state.update { it.copy(count = it.count + 1) }         // atomic read-modify-write
    }
}

data class CounterState(val count: Int = 0)

