data class EditState(val text: String = "", val userMessage: String? = null)

class EditViewModel(private val repository: NoteRepository) : ViewModel() {
    private val _state = MutableStateFlow(EditState())
    val state = _state.asStateFlow()

    fun onSave() = viewModelScope.launch {
        repository.save(_state.value.text)
        _state.update { it.copy(userMessage = "Saved") }
    }

    fun onMessageShown() = _state.update { it.copy(userMessage = null) }
}

