class ComposeViewModel(
    private val repository: DraftRepository,
    private val appScope: CoroutineScope,           // injected, lives as long as the app
    private val workManager: WorkManager
) : ViewModel() {

    // Cancelled if the user leaves right away
    fun loadDraft() = viewModelScope.launch { _draft.value = repository.load() }

    // Continues after the screen is gone
    fun saveDraft(text: String) { appScope.launch { repository.save(text) } }

    // Survives process death
    fun upload(id: String) {
        workManager.enqueue(OneTimeWorkRequestBuilder<UploadWorker>().setInputData(workDataOf("id" to id)).build())
    }
}

class OrdersViewModel(repository: OrderRepository) : ViewModel() {

    val state: StateFlow<OrdersUi> = repository.observeOrders()
        .map<List<Order>, OrdersUi> { OrdersUi.Content(it) }
        .onStart { emit(OrdersUi.Loading) }
        .catch { emit(OrdersUi.Error(it.message)) }
        .stateIn(
            scope = viewModelScope,
            started = SharingStarted.WhileSubscribed(5_000),   // runs only while observed
            initialValue = OrdersUi.Loading
        )
}
